#include "gfx.h"
#include "../platform/mmio.h"
#include "../../fw/font_metrics.h"          /* generated by tools/gen_font_rom.py: FONT_FIRST/LAST and the per-glyph advance (moves to fw2/generated at S7) */

#define OP_RECT 1u
#define OP_CHAR 2u

static uint32_t color_shadow = 0xFFFFFFFFu;
static inline void wait_fifo(void) { while (REG(R_FB_GO) & 1u) { } }
static void set_colors(uint16_t fg, uint16_t bg)
{
    uint32_t v = ((uint32_t)bg << 16) | fg;
    if (v != color_shadow) { color_shadow = v; REG(R_FB_COLOR) = v; }
}

void gfx_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t color)
{
    if (!w || !h || x >= GFX_W || y >= GFX_H) return;
    if (x + w > GFX_W) w = GFX_W - x;
    if (y + h > GFX_H) h = GFX_H - y;
    wait_fifo();
    REG(R_FB_ADDR) = y * GFX_STRIDE + x;
    REG(R_FB_SIZE) = (h << 9) | w;
    set_colors(color, color);
    REG(R_FB_GO) = OP_RECT;
}

static uint32_t glyph_of(char ch)
{
    uint32_t c = (unsigned char)ch;
    return (c < FONT_FIRST || c > FONT_LAST) ? (uint32_t)' ' : c;      /* the atlas holds 0x20..0x7E and nothing else */
}

uint32_t gfx_text_width(const char *s)
{
    uint32_t w = 0;
    for (; *s; s++) w += font_adv[glyph_of(*s) - FONT_FIRST];
    return w;
}

uint32_t gfx_text(uint32_t x, uint32_t y, const char *s, uint16_t fg, uint16_t bg)
{
    if (y + GFX_CELL_H > GFX_H) return x;
    set_colors(fg, bg);
    for (; *s; s++) {
        uint32_t g = glyph_of(*s);
        if (x + FONT_CELL_W > GFX_W) break;      /* a cell past column 400 lands in the next scanline's memory: never draw one */
        wait_fifo();
        REG(R_FB_ADDR) = y * GFX_STRIDE + x;
        REG(R_FB_GO) = OP_CHAR | (g << 3);       /* scale 1x: sx = sy = 0 */
        x += font_adv[g - FONT_FIRST];
    }
    return x;
}
